package com.minecraftmoba.plugin;
import org.bukkit.*;
import org.bukkit.block.*;
import org.bukkit.block.data.Ageable;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.entity.*;
import org.bukkit.event.*;
import org.bukkit.event.block.*;
import org.bukkit.event.entity.*;
import org.bukkit.inventory.ItemStack;
import org.bukkit.util.Vector;
import java.util.*;
/** Infection develops a shared physical Zone; traversal and bloom consume its actual topology. */
final class FungalState implements Listener {
 private record Infection(Player source,LivingEntity target,BlockAddress origin,int until){}
 private static final class Travel {final Player player;final Set<BlockAddress> network;final String branch;final int until;final double originalHealth;Location last;Travel(Player p,Set<BlockAddress> n,String b,int until){player=p;network=n;branch=b;this.until=until;originalHealth=p.getHealth();last=p.getLocation();}}
 private record Angel(Player owner,BlockAddress at,int primedAt,int until){}
 private final MobaPlugin plugin;private final ConfigurationSection cfg;private final DevelopedZones zones;private int clock,ecologyIndex;
 private final Map<UUID,Infection> infections=new HashMap<>();private final Map<UUID,Travel> travels=new HashMap<>();private final Map<UUID,Angel> angels=new HashMap<>();
 FungalState(MobaPlugin p,DevelopedZones zones){plugin=p;this.zones=zones;cfg=p.getConfig().getConfigurationSection("fungalAssassin");}
 private boolean has(Player p){return KitSupport.has(plugin,p,"fungal_assassin")&&plugin.passives().has(p,"creeping_colony");}
 private boolean fungal(Material m){return m==Material.MYCELIUM||m==Material.BROWN_MUSHROOM||m==Material.RED_MUSHROOM||m==Material.MUSHROOM_STEM||m==Material.BROWN_MUSHROOM_BLOCK||m==Material.RED_MUSHROOM_BLOCK;}
 private BlockAddress nearest(Location at){return zones.footprint("fungal").stream().filter(k->k.block()!=null&&fungal(k.block().getType())&&k.world().equals(at.getWorld().getUID())).min(java.util.Comparator.comparingDouble(k->k.block().getLocation().distanceSquared(at))).filter(k->k.block().getLocation().distanceSquared(at)<=cfg.getDouble("networkRange")*cfg.getDouble("networkRange")).orElse(null);}
 private void infect(Player source,LivingEntity target){BlockAddress origin=nearest(source.getLocation());int duration=cfg.getInt("infectionTicks")*(origin==null?1:cfg.getInt("networkDurationMultiplier"));infections.put(target.getUniqueId(),new Infection(source,target,origin,clock+duration));}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void attack(EntityDamageByEntityEvent e){if(e.getFinalDamage()>0&&e.getDamager() instanceof Player p&&has(p)&&e.getEntity() instanceof LivingEntity target&&Targetability.status(target,p)&&!AbilityDamage.active())infect(p,target);}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void placed(BlockPlaceEvent e){if(has(e.getPlayer())&&fungal(e.getBlock().getType())){zones.put(e.getBlock(),e.getPlayer().getUniqueId(),"fungal");zones.save();}}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void broken(BlockBreakEvent e){Angel angel=angels.values().stream().filter(a->a.at.equals(BlockAddress.of(e.getBlock()))).findFirst().orElse(null);if(angel!=null){e.setCancelled(true);e.setDropItems(false);boolean primed=clock>=angel.primedAt;angels.remove(angel.owner.getUniqueId());plugin.kitGlow().release(angel.owner,"angel");e.getBlock().setType(Material.AIR,false);if(primed)bloom(angel);return;}if(e.getBlock().getType()==Material.BROWN_MUSHROOM_BLOCK||e.getBlock().getType()==Material.RED_MUSHROOM_BLOCK){if(nearest(e.getBlock().getLocation())!=null){e.setDropItems(false);e.getBlock().getWorld().dropItemNaturally(e.getBlock().getLocation(),new ItemStack(e.getBlock().getType()==Material.BROWN_MUSHROOM_BLOCK?Material.BROWN_MUSHROOM:Material.RED_MUSHROOM));}}zones.remove(e.getBlock());zones.save();}
 boolean burst(Player p,LivingEntity target,String branch){Infection infection=target==null?null:infections.get(target.getUniqueId());if(infection==null||!infection.source.equals(p))return false;infections.remove(target.getUniqueId());Location at=target.getLocation();int radius=cfg.getInt("territoryRadius");for(int x=-radius;x<=radius;x++)for(int z=-radius;z<=radius;z++){Block b=at.getBlock().getRelative(x,-1,z);if(!KitSupport.loaded(b.getLocation())||plugin.displacement().isReserved(b))continue;if(Set.of(Material.DIRT,Material.GRASS_BLOCK,Material.PODZOL,Material.MYCELIUM).contains(b.getType())){b.setType(Material.MYCELIUM,false);plugin.provenance().mark(b,true);zones.put(b,p.getUniqueId(),"fungal");}}
  if(branch.equals("submersive")&&target.isInWater()){Block ground=at.getBlock();for(int i=0;i<cfg.getInt("aquaticDepth")&&ground.getType()==Material.WATER;i++)ground=ground.getRelative(0,-1,0);if(ground.getType().isSolid()&&!plugin.displacement().isReserved(ground)){ground.setType(Material.MYCELIUM,false);plugin.provenance().mark(ground,true);zones.put(ground,p.getUniqueId(),"fungal");Block plant=ground.getRelative(0,1,0);for(int i=0;i<cfg.getInt("aquaticHeight")&&plant.getType()==Material.WATER;i++){plant.setType(Material.KELP_PLANT,false);plugin.provenance().mark(plant,true);plant=plant.getRelative(0,1,0);}if(plant.getRelative(0,-1,0).getType()==Material.KELP_PLANT)plant.getRelative(0,-1,0).setType(Material.KELP,false);}}
  double hitRadius=cfg.getDouble(branch.equals("airborne_spread")?"airborneHitRadius":"burstHitRadius");for(var enemy:KitSupport.enemies(p,at,hitRadius)){AbilityDamage.deal(enemy,cfg.getDouble("burstDamage"),p);if(branch.equals("airborne_spread")&&!enemy.equals(target))infect(p,enemy);}zones.save();return true;
 }
 boolean travel(Player p,String branch){if(travels.containsKey(p.getUniqueId())){end(p);return true;}BlockAddress origin=nearest(p.getLocation());if(origin==null)return false;Set<BlockAddress> network=zones.connected(origin,"fungal",cfg.getInt("networkCap"),cell->fungal(cell.getType()));if(network.isEmpty())return false;travels.put(p.getUniqueId(),new Travel(p,network,branch,clock+cfg.getInt("travelTicks")));p.setInvisible(true);p.setCollidable(false);return true;}
 private void end(Player p){Travel t=travels.remove(p.getUniqueId());if(t==null)return;p.setInvisible(false);p.setCollidable(true);Location safe=KitSupport.safe(t.last,3);if(safe!=null)p.teleport(safe);if(t.branch.equals("nutrient_cycle")){for(int x=-3;x<=3;x++)for(int z=-3;z<=3;z++){Block b=p.getLocation().getBlock().getRelative(x,0,z);if(b.getType()==Material.BROWN_MUSHROOM||b.getType()==Material.RED_MUSHROOM){if(b.applyBoneMeal(BlockFace.UP))return;}}}}
 boolean angel(Player p,Location at){Angel old=angels.get(p.getUniqueId());if(old!=null){if(clock<old.primedAt)return false;angels.remove(p.getUniqueId());if(old.at.block()!=null)old.at.block().setType(Material.AIR,false);bloom(old);plugin.kitGlow().release(p,"angel");return true;}Block b=at.getBlock();if(!KitSupport.loaded(at)||!b.isEmpty()||plugin.displacement().isReserved(b)||!b.getRelative(0,-1,0).getType().isSolid())return false;b.setType(Material.BROWN_MUSHROOM,false);plugin.provenance().mark(b,true);BlockAddress origin=nearest(at);boolean mature=origin!=null&&zones.connected(origin,"fungal",cfg.getInt("networkCap"),cell->fungal(cell.getType())).stream().mapToInt(zones::development).sum()>=cfg.getInt("instantPrimeMaturity");plugin.kitGlow().acquire(p,"angel");angels.put(p.getUniqueId(),new Angel(p,BlockAddress.of(b),clock+(mature?0:cfg.getInt("primeTicks")),clock+cfg.getInt("angelTicks")));return true;}
 private void bloom(Angel a){Block b=a.at.block();if(b==null)return;Location at=b.getLocation();for(int x=-4;x<=4;x++)for(int z=-4;z<=4;z++){Block mushroom=b.getRelative(x,0,z);if(mushroom.getType()==Material.BROWN_MUSHROOM||mushroom.getType()==Material.RED_MUSHROOM)mushroom.applyBoneMeal(BlockFace.UP);}for(var enemy:KitSupport.enemies(a.owner,at,cfg.getDouble("bloomRadius"))){AbilityDamage.deal(enemy,cfg.getDouble("bloomDamage"),a.owner);if(!enemy.isDead())infect(a.owner,enemy);}}
 boolean hasAngel(Player p){return angels.containsKey(p.getUniqueId());}
 boolean travelling(Player p){return travels.containsKey(p.getUniqueId());}
 void tick(){clock++;if(plugin.inputs()==null)return;
  for(var p:Bukkit.getOnlinePlayers())if(has(p)&&clock%20==0){Block base=p.getLocation().getBlock();for(int x=-3;x<=3;x++)for(int z=-3;z<=3;z++){Block b=base.getRelative(x,-1,z);if(fungal(b.getType()))zones.put(b,p.getUniqueId(),"fungal");}}
  for(var i:List.copyOf(infections.values())){if(clock>=i.until||i.target.isDead()||!i.source.isOnline()){infections.remove(i.target.getUniqueId());continue;}if(clock%cfg.getInt("infectionInterval")==0){AbilityDamage.deal(i.target,cfg.getDouble("infectionDamage"),i.source);if(i.origin!=null&&i.origin.block()!=null&&i.origin.block().getWorld()==i.target.getWorld()&&i.origin.block().getLocation().distanceSquared(i.target.getLocation())<cfg.getDouble("networkRange")*cfg.getDouble("networkRange"))zones.develop(i.origin);if(KitSupport.branch(plugin,i.source,"bursting_spore").equals("airborne_spread"))for(var enemy:KitSupport.enemies(i.source,i.target.getLocation(),cfg.getDouble("infectionSpreadRadius")))if(!infections.containsKey(enemy.getUniqueId()))infect(i.source,enemy);}
   if(KitSupport.branch(plugin,i.source,"bursting_spore").equals("root_network")&&i.origin!=null&&i.origin.block()!=null&&i.target.getWorld()==i.origin.block().getWorld()){Vector back=i.origin.block().getLocation().toVector().subtract(i.target.getLocation().toVector());if(back.lengthSquared()>cfg.getDouble("retentionRadius")*cfg.getDouble("retentionRadius"))KitSupport.push(plugin,i.target,back.normalize().multiply(cfg.getDouble("retentionSpeed")));}}
  for(var t:List.copyOf(travels.values())){Player p=t.player;if(!has(p)||clock>=t.until){end(p);continue;}if(plugin.stun().movementRefused(p))continue;Vector facing=p.getLocation().getDirection().setY(0);if(facing.lengthSquared()<.001)continue;facing.normalize();Vector delta=new Vector();var input=p.getCurrentInput();if(input.isForward())delta.add(facing);if(input.isBackward())delta.subtract(facing);Vector lateral=new Vector(-facing.getZ(),0,facing.getX());if(input.isRight())delta.add(lateral);if(input.isLeft())delta.subtract(lateral);if(delta.lengthSquared()>.001)delta.normalize().multiply(cfg.getDouble("travelSpeed"));Location next=p.getLocation().clone().add(delta);BlockAddress cell=t.network.stream().filter(k->k.block()!=null&&fungal(k.block().getType())).min(java.util.Comparator.comparingDouble(k->k.block().getLocation().distanceSquared(next))).orElse(null);if(cell==null||cell.block().getLocation().distanceSquared(next)>2.5){end(p);continue;}Location step=next.clone();step.setY(cell.y()+.1);p.teleport(step);t.last=step.clone().add(0,.9,0);if(t.branch.equals("hardy")){double cap=plugin.getConfig().getBoolean("features.vitalsScaling.enabled")?Vitals.scaleHealing(cfg.getDouble("hardyCap"),plugin.effectiveMaxHealth(p)):cfg.getDouble("hardyCap");double remaining=t.originalHealth+cap-p.getHealth();if(remaining>0)KitSupport.heal(plugin,p,Math.min(cfg.getDouble("hardyHeal"),plugin.getConfig().getBoolean("features.vitalsScaling.enabled")?Vitals.toEffective(remaining,plugin.effectiveMaxHealth(p)):remaining));}if(t.branch.equals("hyphae_lashers"))for(var enemy:KitSupport.enemies(p,step,1.3))plugin.toolboxStatuses().root(enemy,cfg.getInt("lasherRootTicks"));}
  for(var a:List.copyOf(angels.values()))if(clock>=a.until||a.at.block()!=null&&a.at.block().getType()!=Material.BROWN_MUSHROOM){angels.remove(a.owner.getUniqueId());plugin.kitGlow().release(a.owner,"angel");if(clock<a.until&&clock>=a.primedAt)bloom(a);if(a.at.block()!=null&&a.at.block().getType()==Material.BROWN_MUSHROOM)a.at.block().setType(Material.AIR,false);}
  if(clock%cfg.getInt("ecologyInterval")==0){List<BlockAddress> cells=zones.footprint("fungal");for(int n=0;n<Math.min(cfg.getInt("ecologyBudget"),cells.size());n++){BlockAddress at=cells.get((ecologyIndex++)%cells.size());Block b=at.block();if(b==null)continue;if(!fungal(b.getType())){zones.remove(b);continue;}Block plant=b.getRelative(0,1,0);if(plant.getBlockData() instanceof Ageable age&&age.getAge()<age.getMaximumAge()){var data=(Ageable)age.clone();data.setAge(age.getAge()+1);var event=new BlockGrowEvent(plant,plant.getState());event.getNewState().setBlockData(data);Bukkit.getPluginManager().callEvent(event);if(!event.isCancelled())plant.setBlockData(data,false);}else plant.randomTick();b.randomTick();for(int boost=0;boost<Math.min(3,zones.development(at)/5);boost++){b.randomTick();plant.randomTick();}}zones.save();}
 }
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void intangible(EntityDamageEvent e){if(e.getEntity() instanceof Player p&&travels.containsKey(p.getUniqueId())&&(e.getCause()==EntityDamageEvent.DamageCause.SUFFOCATION||e.getCause()==EntityDamageEvent.DamageCause.CONTACT))e.setCancelled(true);}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void spread(BlockSpreadEvent e){if(fungal(e.getNewState().getType())&&zones.contains(BlockAddress.of(e.getSource()),"fungal")){var author=zones.author(BlockAddress.of(e.getSource()));if(author!=null)zones.put(e.getBlock(),author,"fungal");}}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void growth(org.bukkit.event.world.StructureGrowEvent e){if(nearest(e.getLocation())!=null)for(var state:e.getBlocks())if(fungal(state.getType())){plugin.provenance().mark(state.getBlock(),true);BlockAddress origin=nearest(e.getLocation());UUID author=origin==null?null:zones.author(origin);if(author!=null)zones.put(state.getBlock(),author,"fungal");}}
 void forget(Player p){end(p);plugin.kitGlow().release(p,"angel");infections.values().removeIf(i->i.source.equals(p));Angel a=angels.remove(p.getUniqueId());if(a!=null&&a.at.block()!=null)a.at.block().setType(Material.AIR,false);}
 void close(){for(var t:List.copyOf(travels.values()))end(t.player);for(var a:List.copyOf(angels.values()))forget(a.owner);infections.clear();zones.save();}
}
